func (q *Queries) IsIssueConveyorStalled(ctx context.Context, arg IsIssueConveyorStalledParams) (bool, error) {
	row := q.db.QueryRow(ctx, isIssueConveyorStalled, arg.ID, arg.Before)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

