const setTaskConveyorAction = `-- name: SetTaskConveyorAction :exec
UPDATE agent_task_queue SET
    conveyor_action_id = $1,
    handoff_note = $2,
    context = COALESCE(context, '{}'::jsonb) || $3::jsonb
WHERE id = $4 AND conveyor_action_id IS NULL
`

type SetTaskConveyorActionParams struct {
	ActionID    pgtype.UUID `json:"action_id"`
	HandoffNote pgtype.Text `json:"handoff_note"`
	TaskContext []byte      `json:"task_context"`
	ID          pgtype.UUID `json:"id"`
}

// Binds a rerun successor to the action its failed predecessor served and
// gives it the route's instructions, which a plain rerun does not carry.
func (q *Queries) SetTaskConveyorAction(ctx context.Context, arg SetTaskConveyorActionParams) error {
	_, err := q.db.Exec(ctx, setTaskConveyorAction,
		arg.ActionID,
		arg.HandoffNote,
		arg.TaskContext,
		arg.ID,
	)
	return err
}
